package com.muthumol.player.dummy;
import android.content.*;import android.os.*;import java.util.*;import java.util.concurrent.*;import java.util.function.Consumer;import org.json.*;
/** Public, title-only lookups. No Telegram identifiers or captions are sent to providers. */
final class MetadataStore {
 static MetadataStore singleton;static synchronized MetadataStore get(Context c){if(singleton==null)singleton=new MetadataStore(c.getApplicationContext());return singleton;}
 final Context c;final SharedPreferences p;final ExecutorService worker=Executors.newFixedThreadPool(2);final Handler ui=new Handler(Looper.getMainLooper());MetadataStore(Context c){this.c=c;p=c.getSharedPreferences("metadata-v2",0);}
 String key(Movie m){return ArtworkStore.hash(MovieDetails.override(c,m));}void invalidate(Movie m){p.edit().remove(key(m)).apply();}
 void load(Movie m,Consumer<JSONObject> callback){String id=key(m);worker.execute(()->{JSONObject result;try{String cached=p.getString(id,"");boolean fresh=!cached.isEmpty()&&System.currentTimeMillis()-p.getLong(id+":time",0)<7L*86400000;result=fresh?new JSONObject(cached):fetch(m);if(!fresh&&!result.optString("overview").isEmpty())p.edit().putString(id,result.toString()).putLong(id+":time",System.currentTimeMillis()).apply();}catch(Exception e){result=new JSONObject();try{result.put("overview","Description is currently unavailable.");}catch(Exception ignored){}}JSONObject value=result;ui.post(()->callback.accept(value));});}
 JSONObject fetch(Movie m)throws Exception{MediaTitle t=MediaTitle.parse(MovieDetails.override(c,m));JSONObject result=new JSONObject(),ratings=new JSONObject();result.put("ratings",ratings);if(t.episodic()){JSONArray search=new JSONArray(new String(ArtworkStore.fetch("https://api.tvmaze.com/search/shows?q="+ArtworkStore.enc(t.name),524288),"UTF-8"));JSONObject show=ArtworkStore.pickShow(t,search);if(show!=null){result.put("overview",plain(show.optString("summary"))).put("genres",show.optJSONArray("genres")==null?"":show.getJSONArray("genres").join(" · ").replace("\"","")).put("source","TVmaze");JSONObject rating=show.optJSONObject("rating");if(rating!=null&&!rating.isNull("average"))ratings.put("TVmaze",rating.opt("average")+" / 10");}}
 try{JSONObject wiki=new JSONObject(new String(ArtworkStore.fetch("https://en.wikipedia.org/w/api.php?action=query&format=json&formatversion=2&generator=search&gsrsearch="+ArtworkStore.enc(t.name+(t.year>0?" "+t.year:"")+(t.episodic()?" television series":" film"))+"&gsrlimit=5&prop=extracts%7Cpageprops&exintro=1&explaintext=1&exchars=2500",524288),"UTF-8"));JSONArray pages=wiki.optJSONObject("query")==null?null:wiki.getJSONObject("query").optJSONArray("pages");if(pages!=null)for(int i=0;i<pages.length();i++){JSONObject page=pages.getJSONObject(i);String title=page.optString("title"),summary=page.optString("extract");if(MediaTitle.similarity(t.name,title.replaceAll("\\s*\\([^)]*\\)",""))<.85||t.year>0&&!title.contains(t.year+"")&&!summary.contains(t.year+""))continue;if(!result.has("overview"))result.put("overview",summary).put("source","Wikipedia");JSONObject props=page.optJSONObject("pageprops");if(props!=null)try{readRatings(props.optString("wikibase_item"),ratings);}catch(Exception ignored){}break;}}catch(Exception ignored){}return result;}
 static String plain(String html){return android.text.Html.fromHtml(html,android.text.Html.FROM_HTML_MODE_LEGACY).toString();}
 void readRatings(String entity,JSONObject out)throws Exception{if(!entity.matches("Q[0-9]+"))return;JSONObject root=new JSONObject(new String(ArtworkStore.fetch("https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&ids="+entity+"&props=claims",524288),"UTF-8"));JSONObject data=root.getJSONObject("entities").optJSONObject(entity);if(data==null)return;JSONArray claims=data.optJSONObject("claims")==null?null:data.getJSONObject("claims").optJSONArray("P444");if(claims==null)return;Map<String,String> sites=new LinkedHashMap<>();for(int i=0;i<claims.length();i++){JSONObject claim=claims.getJSONObject(i),qual=claim.optJSONObject("qualifiers");JSONArray reviewed=qual==null?null:qual.optJSONArray("P447");if(reviewed==null)continue;String score=claim.getJSONObject("mainsnak").optJSONObject("datavalue")==null?"":claim.getJSONObject("mainsnak").getJSONObject("datavalue").optString("value");for(int j=0;j<reviewed.length();j++){JSONObject value=reviewed.getJSONObject(j).optJSONObject("datavalue");if(value!=null&&value.optJSONObject("value")!=null)sites.put(value.getJSONObject("value").optString("id"),score);}}for(Map.Entry<String,String> site:sites.entrySet()){if(!site.getKey().matches("Q[0-9]+"))continue;JSONObject response=new JSONObject(new String(ArtworkStore.fetch("https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&ids="+site.getKey()+"&props=labels&languages=en",131072),"UTF-8"));JSONObject label=response.getJSONObject("entities").getJSONObject(site.getKey()).optJSONObject("labels");String name=label==null||label.optJSONObject("en")==null?"":label.getJSONObject("en").optString("value");if(name.equalsIgnoreCase("IMDb")||name.toLowerCase(Locale.ROOT).contains("rotten tomatoes")||name.equalsIgnoreCase("Metacritic"))out.put(name,site.getValue());}}
}
